let loading;
function pageFlipLibrary(){if(window.St?.PageFlip)return Promise.resolve(window.St.PageFlip);if(!loading)loading=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=window.__AFTERIMAGE_RESOURCES?.['vendor/page-flip.js']||new URL('./vendor/page-flip.js',import.meta.url).href;s.onload=()=>resolve(window.St.PageFlip);s.onerror=()=>{loading=null;reject(new Error('翻页组件加载失败'))};document.head.append(s)});return loading;}
const image=src=>new Promise((res,rej)=>{if(!src)return res(null);const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=src});
export async function pageArt(page,index,c){const ca=Object.assign(document.createElement('canvas'),{width:768,height:1024}),x=ca.getContext('2d');x.fillStyle=index===0?'#243b3e':'#f3eddf';x.fillRect(0,0,768,1024);const im=await image(page.image);let y=100;if(im){const box=index===0?{x:24,y:24,w:720,h:976}:{x:62,y:80,w:644,h:410},sc=Math.max(box.w/im.width,box.h/im.height);x.save();x.beginPath();x.rect(box.x,box.y,box.w,box.h);x.clip();x.drawImage(im,box.x-(im.width*sc-box.w)/2,box.y-(im.height*sc-box.h)/2,im.width*sc,im.height*sc);x.restore();y=550;}x.fillStyle=index===0?'#f7f0df':'#35413b';x.font=index===0?'42px serif':'22px serif';if(index===0){x.fillStyle='#15272cb8';x.fillRect(24,700,720,300);x.fillStyle='#f7f0df';y=800;}for(const paragraph of page.text.split('\n')){let line='';for(const ch of paragraph){if(x.measureText(line+ch).width>620){x.fillText(line,74,y);y+=index===0?54:36;line=ch}else line+=ch;}x.fillText(line,74,y);y+=index===0?54:44;if(y>950)break;}if(index){x.textAlign='center';x.font='14px serif';x.fillText(String(index),384,981);}return ca;}
export async function openBookReader({c,stage,status,save,download}){const PageFlip=await pageFlipLibrary();if(!Array.isArray(c.bookPages)||!c.bookPages.length)c.bookPages=[{text:c.title||'COLLECTED MOMENTS',image:c.front||''},{text:c.pageLeft||'',image:c.pageLeftImage||''},{text:c.pageRight||'',image:c.pageRightImage||''},{text:'',image:''},{text:'',image:''},{text:c.subtitle||'AFTERIMAGE / PRIVATE LIBRARY',image:c.back||''}];
 const overlay=document.createElement('section');overlay.className='book-reader';overlay.innerHTML='<header><strong>阅读与翻页</strong><span id="bookPageNumber"></span><button data-book="close">返回物件</button></header><div class="book-paper-stage"></div><div class="book-reader-tools"><button data-book="previous">← 上一页</button><button data-book="next">下一页 →</button><button data-book="add">＋ 添加页</button><button data-book="remove">删除当前页</button></div><div class="book-editor"><label>当前页文字<textarea rows="4" maxlength="8000"></textarea></label><label>当前页图片<input type="file" accept="image/png,image/jpeg,image/webp"></label><button data-book="apply">更新书页</button><button data-book="png">导出当前页 PNG</button><button data-book="save">保存书籍内容</button></div>';stage.append(overlay);let flip=null,index=0,closed=false;const host=overlay.querySelector('.book-paper-stage'),text=overlay.querySelector('textarea'),file=overlay.querySelector('input');let art=[];
 const sync=()=>{if(closed)return;index=Math.max(0,Math.min(c.bookPages.length-1,flip?.getCurrentPageIndex()||0));text.value=c.bookPages[index].text;overlay.querySelector('#bookPageNumber').textContent=(index+1)+' / '+c.bookPages.length;};
 async function rebuild(){art=await Promise.all(c.bookPages.map((p,i)=>pageArt(p,i,c)));if(closed)return;flip?.destroy();const el=document.createElement('div');host.replaceChildren(el);const width=Math.min(340,Math.max(150,host.clientWidth/2-12));flip=new PageFlip(el,{width:384,height:512,size:'stretch',minWidth:150,maxWidth:420,minHeight:200,maxHeight:560,showCover:true,drawShadow:true,maxShadowOpacity:.35,flippingTime:800,mobileScrollSupport:false,useMouseEvents:true,startPage:Math.min(index,c.bookPages.length-1)});flip.loadFromImages(art.map(a=>a.toDataURL('image/jpeg',.92)));flip.on('flip',sync);flip.on('init',sync);text.value=c.bookPages[index].text;overlay.querySelector('#bookPageNumber').textContent=(index+1)+' / '+c.bookPages.length;}
 overlay.querySelector('[data-book=previous]').onclick=()=>flip?.flipPrev();overlay.querySelector('[data-book=next]').onclick=()=>flip?.flipNext();overlay.querySelector('[data-book=add]').onclick=async()=>{if(c.bookPages.length>=24)return status('最多24页');c.bookPages.splice(index+1,0,{text:'',image:''});index++;await rebuild()};overlay.querySelector('[data-book=remove]').onclick=async()=>{if(c.bookPages.length<=2)return status('至少保留两页');c.bookPages.splice(index,1);index=Math.min(index,c.bookPages.length-1);await rebuild()};
 overlay.querySelector('[data-book=apply]').onclick=async()=>{c.bookPages[index].text=text.value;const f=file.files[0];try{if(f){if(f.size>8000000)throw new Error('图片需小于8MB');const src=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)}),im=await image(src),ca=Object.assign(document.createElement('canvas'),{width:1200,height:Math.max(1,Math.min(2400,Math.round(im.height/im.width*1200)))});ca.getContext('2d').drawImage(im,0,0,ca.width,ca.height);c.bookPages[index].image=ca.toDataURL('image/jpeg',.92);file.value='';}await rebuild()}catch(e){status(e.message)}};overlay.querySelector('[data-book=png]').onclick=async()=>{const a=await pageArt({...c.bookPages[index],text:text.value},index,c),blob=await new Promise(r=>a.toBlob(r,'image/png'));await download(blob,'余像-书页-'+(index+1)+'.png')};overlay.querySelector('[data-book=save]').onclick=async()=>{c.bookPages[index].text=text.value;await save(c);status('多页书籍内容已保存到工程')};const close=()=>{if(closed)return;closed=true;flip?.destroy();overlay.remove()};overlay.querySelector('[data-book=close]').onclick=close;await rebuild();return close;}
